import sys
from collections import deque

def connect(grid, g, i, j, s, t):
    n = len(grid) - 1
    m = len(grid[0]) - 1
    if s <= 0 or t <= 0 or s > n or t > m:
        return
    g[grid[i][j]].append(grid[s][t])

def maxMatching(g, m, n):
    pairU = [0] * (m + 1)
    pairV = [0] * (n + 1)
    dist = [0] * (m + 1)
    matchCount = 0

    def bfs():
        queue = deque()
        for u in range(1, m + 1):
            if pairU[u] == 0:
                dist[u] = 0
                queue.append(u)
            else:
                dist[u] = float('inf')
        maxDist = float('inf')
        while queue:
            u = queue.popleft()
            if dist[u] < maxDist:
                for v in g[u]:
                    if pairV[v] == 0:
                        maxDist = dist[u] + 1
                    elif dist[pairV[v]] == float('inf'):
                        dist[pairV[v]] = dist[u] + 1
                        queue.append(pairV[v])
        return maxDist != float('inf')

    def dfs(u):
        if u != 0:
            for v in g[u]:
                if pairV[v] == 0 or (dist[pairV[v]] == dist[u] + 1 and dfs(pairV[v])):
                    pairU[u] = v
                    pairV[v] = u
                    return True
            dist[u] = float('inf')
            return False
        return True

    while bfs():
        for u in range(1, m + 1):
            if pairU[u] == 0 and dfs(u):
                matchCount += 1
    return matchCount

def main():
    input_line = sys.stdin.readline().strip()
    line = input_line.split()
    n = int(line[0])
    m = int(line[1])
    totalCost = 0

    if n > 100:
        excessN = (n - 100) % 6
        quotientN = (n - 100) // 6
        totalCost += quotientN * 6 * m
        n = 100 + excessN

    if m > 100:
        excessM = (m - 100) % 6
        quotientM = (m - 100) // 6
        totalCost += quotientM * 6 * n
        m = 100 + excessM

    grid = [[0] * (m + 1) for _ in range(n + 1)]
    uCount = 1
    vCount = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i + j) % 2 == 0:
                grid[i][j] = uCount
                uCount += 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i + j) % 2 != 0:
                grid[i][j] = vCount
                vCount += 1

    adjacency = [[] for _ in range(uCount)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i + j) % 2 == 0:
                connect(grid, adjacency, i, j, i - 3, j)
                connect(grid, adjacency, i, j, i - 2, j - 1)
                connect(grid, adjacency, i, j, i - 2, j + 1)
                connect(grid, adjacency, i, j, i, j - 3)
                connect(grid, adjacency, i, j, i - 1, j - 2)
                connect(grid, adjacency, i, j, i + 1, j - 2)
                connect(grid, adjacency, i, j, i, j + 3)
                connect(grid, adjacency, i, j, i - 1, j + 2)
                connect(grid, adjacency, i, j, i + 1, j + 2)
                connect(grid, adjacency, i, j, i + 3, j)
                connect(grid, adjacency, i, j, i + 2, j - 1)
                connect(grid, adjacency, i, j, i + 2, j + 1)

    max_match = maxMatching(adjacency, uCount - 1, vCount - 1)
    totalCost += 2 * max_match
    print(totalCost)

if __name__ == "__main__":
    main()

